body {
    margin: 0;
    padding: 0;
    background: black;
    font-family: 'Courier New', monospace;
    color: #00ff00;
    overflow: hidden;
}

#terminal {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 800px;
    height: 600px;
    background: #111;
    border: 10px solid #333;
    border-radius: 10px;
    box-shadow: 0 0 20px rgba(0, 255, 0, 0.5);
    animation: flicker 2s infinite alternate;
}

#screen {
    width: 100%;
    height: 100%;
    background: black;
    padding: 20px;
    box-sizing: border-box;
    position: relative;
}

#screen::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: repeating-linear-gradient(
        0deg,
        rgba(0, 255, 0, 0.03) 0px,
        rgba(0, 255, 0, 0.03) 2px,
        transparent 2px,
        transparent 4px
    );
    pointer-events: none;
}

#output {
    height: 80%;
    white-space: pre-wrap;
    font-size: 18px;
    line-height: 1.5;
}

#buttons {
    display: flex;
    justify-content: space-around;
    margin-top: 20px;
}

button {
    background: #333;
    color: #00ff00;
    border: 2px solid #00ff00;
    padding: 10px 20px;
    font-family: inherit;
    font-size: 16px;
    cursor: pointer;
    transition: background 0.3s;
}

button:hover {
    background: #00ff00;
    color: black;
}

button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

@keyframes flicker {
    0% { opacity: 1; }
    100% { opacity: 0.98; }
}

