// Compute total weight
let totalWeight = items.reduce((sum, item) => sum + item.weight, 0);

// Weighted random picker
function getRandomItem() {
    let random = Math.random() * totalWeight;
    let cumulative = 0;
    for (let item of items) {
        cumulative += item.weight;
        if (random < cumulative) {
            return item;
        }
    }
}

// Generate 6 offers
let offers = [];
for (let i = 0; i < 6; i++) {
    offers.push(getRandomItem());
}

let currentOfferIndex = 0;

const output = document.getElementById('output');
const acceptBtn = document.getElementById('accept');
const rerollBtn = document.getElementById('reroll');

// Typewriter effect
function typeWriter(text, element, speed = 50) {
    element.textContent = '';
    let i = 0;
    const timer = setInterval(() => {
        if (i < text.length) {
            element.textContent += text.charAt(i);
            i++;
        } else {
            clearInterval(timer);
        }
    }, speed);
}

// Show current offer
function showOffer() {
    const item = offers[currentOfferIndex];
    const text = `Item: ${item.name}\nRarity: ${item.rarity}\nPrice: $${item.price}\n`;
    typeWriter(text, output);
}

// Initial show
showOffer();

// Re-roll
rerollBtn.addEventListener('click', () => {
    if (currentOfferIndex < 5) {
        currentOfferIndex++;
        showOffer();
        if (currentOfferIndex === 5) {
            rerollBtn.disabled = true;
        }
    }
});

// Accept (for now, just log)
acceptBtn.addEventListener('click', () => {
    const item = offers[currentOfferIndex];
    alert(`Accepted: ${item.name} for $${item.price}`);
});

