@keyframes explosion {
    0% {
        transform: scale(1);
        opacity: 1;
    }
    50% {
        transform: scale(1.2);
        filter: brightness(2);
    }
    100% {
        transform: scale(2);
        opacity: 0;
    }
}

@keyframes shake {
    0%, 100% { transform: translate(0, 0) rotate(0deg); }
    25% { transform: translate(-10px, -10px) rotate(2deg); }
    50% { transform: translate(10px, 10px) rotate(-2deg); }
    75% { transform: translate(-10px, 10px) rotate(-2deg); }
}

#offer-counter {
    position: absolute;
    top: 20px;
    left: 20px;
    color: #b19cd9;
    font-size: 16px;
    font-weight: bold;
    border: 2px solid #8a2be2;
    padding: 8px 12px;
    background: rgba(0, 0, 0, 0.5);
    border-radius: 5px;
}

#stats-panel {
    position: absolute;
    top: 20px;
    right: 20px;
    color: #b19cd9;
    font-size: 12px;
    border: 2px solid #8a2be2;
    padding: 12px;
    background: rgba(0, 0, 0, 0.7);
    border-radius: 5px;
    max-width: 180px;
    max-height: 300px;
    overflow-y: auto;
}

#stats-title {
    font-weight: bold;
    color: #ffd700;
    margin-bottom: 8px;
    text-align: center;
    border-bottom: 1px solid #8a2be2;
    padding-bottom: 5px;
}

#stats-list {
    font-size: 11px;
    line-height: 1.4;
}

#inventory-panel {
    position: absolute;
    bottom: 20px;
    right: 20px;
    color: #b19cd9;
    font-size: 12px;
    border: 2px solid #8a2be2;
    padding: 12px;
    background: rgba(0, 0, 0, 0.7);
    border-radius: 5px;
    max-width: 180px;
    max-height: 200px;
    overflow-y: auto;
}

#inventory-title {
    font-weight: bold;
