    margin-bottom: 8px;
    text-align: center;
    border-bottom: 1px solid #8a2be2;
    padding-bottom: 5px;
}

#inventory-list {
    font-size: 11px;
    line-height: 1.4;
}

#easter-egg {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    display: none;
    z-index: 1000;
}

#easter-egg img {
    width: 300px;
    height: 300px;
    animation: fadeIn 0.5s ease-in;
}

#terminal.exploding {
    animation: explosion 1s ease-out forwards, shake 0.5s ease-in-out;
}

let stats = {}; // Track what was pulled
let inventory = []; // Track what was accepted
let easterEggActive = false;

const output = document.getElementById('output');
const acceptBtn = document.getElementById('accept');
const rerollBtn = document.getElementById('reroll');
const counterText = document.getElementById('counter-text');
const statsList = document.getElementById('stats-list');
const inventoryList = document.getElementById('inventory-list');
const easterEgg = document.getElementById('easter-egg');
const terminal = document.getElementById('terminal');

// Typewriter effect
function typeWriter(text, element, speed = 50) {
    element.textContent = '';
    let i = 0;
    const timer = setInterval(() => {
        if (i < text.length) {
            element.textContent += text.charAt(i);
            i++;
        } else {
            clearInterval(timer);
        }
    }, speed);
}

// Rarity color map
const rarityColors = {
    'Mil-Spec': '#0066ff',
    'Restricted': '#9933ff',
    'Classified': '#ff1493',
    'Covert': '#ff0000',
    'Gloves': '#ffd700'
};

// Update statistics display
function updateStats() {
    let html = '';
    for (let rarity in stats) {
        html += `<div>${rarity}: ${stats[rarity]}</div>`;
    }
    statsList.innerHTML = html || '<div>None yet</div>';
}

// Update inventory display
function updateInventory() {
    let html = '';
    inventory.forEach(item => {
        html += `<div style="color: ${rarityColors[item.rarity]}">${item.name}</div>`;
    });
    inventoryList.innerHTML = html || '<div>Empty</div>';
}

// Show current offer
function showOffer() {
    const item = offers[currentOfferIndex];
    const color = rarityColors[item.rarity] || '#b19cd9';
    
    // Update counter
    counterText.textContent = `${currentOfferIndex + 1}/6`;
    
    let html = '';
    if (item.image) {
        html += `<img src="low-poly/${item.image}" alt="${item.name}" style="max-width:180px; max-height:180px; margin-bottom:15px; animation: fadeIn 1s ease-in;">`;
